CREATE OR REPLACE FUNCTION public.reconcile_workforce_attendance(_org uuid DEFAULT NULL::uuid)
 RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$ DECLARE o uuid; n integer; BEGIN IF auth.role()='service_role' OR session_user IN ('postgres','supabase_admin') AND auth.uid() IS NULL THEN o:=_org; ELSE o:=public.current_org_id(); IF o IS NULL OR NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') OR _org IS NOT NULL AND _org<>o THEN RAISE EXCEPTION 'Company attendance access required'; END IF; END IF;
INSERT INTO public.workforce_shifts(org_id,employee_id,shift_date,scheduled_start,scheduled_end,break_minutes) SELECT s.org_id,s.employee_id,day::date,(day::date+s.shift_start) AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'),((day::date+CASE WHEN s.shift_end<s.shift_start THEN 1 ELSE 0 END)+s.shift_end) AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'),s.break_minutes FROM public.workforce_schedules s LEFT JOIN public.workforce_clock_settings c ON c.org_id=s.org_id LEFT JOIN public.payroll_go_live g ON g.org_id=s.org_id CROSS JOIN LATERAL generate_series((now() AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'))::date-1,(now() AT TIME ZONE coalesce(c.timezone,'America/St_Lucia'))::date,interval '1 day') day WHERE s.enabled AND (o IS NULL OR s.org_id=o) AND (g.start_date IS NULL OR day::date>=g.start_date) AND extract(dow FROM day)=ANY(s.days_of_week) AND EXISTS(SELECT 1 FROM public.payroll_employee_directory e WHERE e.user_id=s.employee_id AND e.org_id=s.org_id AND e.deleted_at IS NULL AND lower(e.status)='active') ON CONFLICT(org_id,employee_id,shift_date) DO NOTHING;
INSERT INTO public.workforce_alerts(org_id,shift_id,employee_id,missing_type) SELECT w.org_id,w.id,w.employee_id,CASE WHEN w.clock_in IS NULL THEN 'clock_in' ELSE 'clock_out' END FROM public.workforce_shifts w LEFT JOIN public.payroll_go_live g ON g.org_id=w.org_id WHERE (o IS NULL OR w.org_id=o) AND (g.start_date IS NULL OR w.shift_date>=g.start_date) AND w.review_status='pending' AND (w.clock_in IS NULL AND w.scheduled_start<now()-interval '15 minutes' OR w.clock_in IS NOT NULL AND w.clock_out IS NULL AND coalesce(w.scheduled_end,w.clock_in+interval '16 hours')<now()-interval '15 minutes') ON CONFLICT(shift_id,missing_type) DO NOTHING;
GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $function$;